export const PLAYTEST_CHECKPOINTS=[
 {id:1,title:'Found a town',description:'Go from empty terrain to a functioning, saved town.',steps:[['found','Lay roads, zone homes and workplaces, and connect electricity.'],['services','Complete the first-town guide through water, job access, waste collection and three surplus months.'],['restore','Save or export the city, then restore it and check the result.']],prompt:'Which construction controls or growth requirements were unclear?'},
 {id:2,title:'Run essential utilities',description:'Diagnose service shortages and manage disposal capacity.',steps:[['water','Repair an unserved water network using its diagnostics and underground view.'],['waste','Compare disposal capacity, garbage collection and facility aging.'],['trends','Use utility trends to distinguish available capacity from delivered service.']],prompt:'Could you explain why an occupied lot lacked service and how to fix it?'},
 {id:3,title:'Balance the city',description:'Weigh taxes, funding, loans, policies and business locations.',steps:[['budget','Use the budget preview to create a surplus or recover from a deficit.'],['trade','Compare a utility trade or ordinance with local provision.'],['business','Compare two business sites and explain their budget and neighborhood effects.']],prompt:'Which financial tradeoff still required guessing?'},
 {id:4,title:'Serve residents',description:'Improve health, learning and public safety where residents need them.',steps:[['coverage','Inspect two neighborhoods with different service access.'],['fund','Place and fund a civic service, then compare coverage again.'],['outcomes','Track crime, age-group education or life expectancy over time.']],prompt:'Did maps and reports explain the outcomes of your service decisions?'},
 {id:5,title:'Connect and customize a metropolis',description:'Improve transport and document your city.',steps:[['route','Build a useful bus, rail, subway or highway route and inspect its usage.'],['crossing','Build or inspect a bridge or tunnel and check its connections.'],['album','Capture a captioned city snapshot and export an album.']],prompt:'Did route diagnostics and camera controls help you develop the city?'},
 {id:6,title:'Face and author challenges',description:'Recover from a disaster and try a prepared scenario.',steps:[['respond','Respond to a disaster with its available response tools.'],['recover','Restore damaged services and check recovery.'],['scenario','Play a prepared challenge and inspect its goals and outcome.']],prompt:'Were warnings, response actions, recovery and scenario goals understandable?'},
 {id:7,title:'Design your own skyline',description:'Create custom buildings with editable layers, paint and portable files.',steps:[['construct','Build an arch or overhang using independent layers and edit planes.'],['paint','Paint one floor differently from its neighbor, sample both materials, and undo/redo the stroke.'],['share','Export and reimport a building file, then apply the draft to its city style.']],prompt:'Could you build, paint, inspect and reuse the shape you intended?'},
 {id:8,title:'Author a changing scenario',description:'Build and play a challenge whose events and goals develop over time.',steps:[['author','Create a custom goal and a conditional event or message.'],['change','Use goal activation, variables or a reusable program to change the challenge during play.'],['replay','Export, restore and replay the challenge; verify its saved progress and outcome.']],prompt:'Did the authoring tools let you express and verify the intended challenge?'}
];
function openPlaytestDialog(ui,title,body){ui.dialog(title,body);document.getElementById('dialog')?.scrollTo?.(0,0);document.getElementById('closeDialog')?.focus?.({preventScroll:true});}
const checkpoint=id=>PLAYTEST_CHECKPOINTS.find(c=>c.id===id)||PLAYTEST_CHECKPOINTS[0];
export function readPlaytestFeedback(storage,id){const c=checkpoint(id);let notes='',checked=[];try{notes=storage.getItem(`sims3000.feedback.m${c.id}`)||'';}catch{}try{const parsed=JSON.parse(storage.getItem(`sims3000.feedback.checks.m${c.id}`)||'[]');if(Array.isArray(parsed))checked=c.steps.map(([key])=>key).filter(key=>parsed.includes(key));}catch{}return{notes,checked};}
export function feedbackText(id,notes,checked){const c=checkpoint(id);return`SIMS3000 · Checkpoint ${c.id}: ${c.title}\n\nPlayer-reported playtest steps:\n${c.steps.map(([key,text])=>`[${checked.includes(key)?'x':' '}] ${text}`).join('\n')}\n\n${c.prompt}\n\nNotes:\n${notes}\n`;}
export function showPlaytestFeedback(ui,id=1){const c=checkpoint(id),saved=readPlaytestFeedback(ui.storage,c.id);openPlaytestDialog(ui,`Checkpoint ${c.id} · ${c.title}`,`<p>${c.description}</p><p>Mark the tasks you have tried, then record what worked and what should change. Checkmarks are your playtest notes, not automatic proof that the simulation is correct.</p>${c.steps.map(([key,text])=>`<label class="ordinance"><input type="checkbox" data-playtest-step="${key}" ${saved.checked.includes(key)?'checked':''}>${text}</label>`).join('')}<p><strong>${c.prompt}</strong></p><label>Your notes<textarea id="reviewNotes" rows="5" placeholder="What felt right? What happened, and what did you expect?"></textarea></label><div class="actions"><button id="launchPlaytest">Open game tools for this checkpoint</button><button class="primary" id="saveReview">Save feedback notes</button><button id="exportReview">Download notes</button><button id="backPlaytests">All checkpoints</button></div><p class="fine">Save before opening game tools. Notes and checkmarks stay in this browser. They are not sent automatically; paste or attach the downloaded notes in this task when ready.</p>`);
 const notes=document.getElementById('reviewNotes');notes.value=saved.notes;const checked=()=>[...document.querySelectorAll('[data-playtest-step]')].filter(el=>el.checked).map(el=>el.dataset.playtestStep);
 document.getElementById('saveReview').onclick=()=>{try{ui.storage.setItem(`sims3000.feedback.m${c.id}`,notes.value);ui.storage.setItem(`sims3000.feedback.checks.m${c.id}`,JSON.stringify(checked()));ui.notify('Feedback notes and playtest steps saved on this browser.');}catch{ui.notify('Storage unavailable. Download your notes instead.');}};
 document.getElementById('exportReview').onclick=()=>ui.download(`sims3000-milestone-${c.id}-feedback.txt`,feedbackText(c.id,notes.value,checked()),'text/plain');document.getElementById('launchPlaytest').onclick=()=>ui.launch(c.id);document.getElementById('backPlaytests').onclick=ui.roadmap;
}
export function showPlaytestRoadmap(ui){openPlaytestDialog(ui,'The road to a metropolis',`<p>Eight playable feedback checkpoints, grouped by the decisions and tools they add. You can try them in any order that suits your city.</p>${PLAYTEST_CHECKPOINTS.map(c=>{const saved=readPlaytestFeedback(ui.storage,c.id);return`<article class="milestone"><small>CHECKPOINT ${c.id} · READY TO TRY</small><h3>${c.title}</h3><p>${c.description}</p><p>${saved.checked.length} / ${c.steps.length} tasks marked tried${saved.notes?' · saved notes available':''}.</p><button data-review="${c.id}">Open checkpoint ${c.id}</button></article>`;}).join('')}<p>This reconstruction is not verified full manual parity. Remaining work includes the complete structure and ordinance catalogs, original shipped scenarios and file formats, further scenario-language coverage, independently simulated neighbors, and broader art, audio, balance and performance acceptance. Many formulas and capacities are reconstruction tuning.</p><a href="https://excalet.com/technology/game_manuals/simcity_3000_unlimited.pdf" target="_blank" rel="noreferrer">Read the source manual</a>`);document.querySelectorAll('[data-review]').forEach(button=>button.onclick=()=>ui.review(Number(button.dataset.review)));}
